-- Add GV model/variant references to assets (companion to 20260624000001,
-- mirrors fleet migrations 00076/00077).
-- equipment_model_id   -> Global Values equipment_models catalog id
-- equipment_variant_id -> Global Values equipment_class_variants catalog id
--                         (spec band, e.g. compact/medium/large; used when the
--                         asset has no identifiable concrete make/model)
-- No FKs: GV lives in a separate Supabase project, loose references only.

ALTER TABLE inventory.assets
  ADD COLUMN IF NOT EXISTS equipment_model_id uuid,
  ADD COLUMN IF NOT EXISTS equipment_variant_id uuid;

COMMENT ON COLUMN inventory.assets.equipment_model_id IS
  'Global Values equipment_models catalog id (equipment assets only).';
COMMENT ON COLUMN inventory.assets.equipment_variant_id IS
  'Global Values equipment_class_variants catalog id (spec band; equipment assets without a concrete model).';

-- One-time backfill copied from fleet stage on 2026-07-09, keyed by
-- fleet_assets.inventory_asset_id -> inventory.assets.id. 377 rows: 273 with a
-- model, 104 generic assets with a spec-band variant. The 5 stencil-set assets
-- stay unlinked (no GV class yet).
create temp table _gv_map (asset_id uuid, model_id uuid, variant_id uuid);

update inventory.assets a
set equipment_model_id   = coalesce(a.equipment_model_id, m.model_id),
    equipment_variant_id = coalesce(a.equipment_variant_id, m.variant_id)
from _gv_map m
where a.id = m.asset_id;

drop table _gv_map;
